import java.io.BufferedReader;
import java.io.InputStreamReader;

public class OneBasedArithmetic {
    public static void main(String[] args) throws Exception {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        long n = Long.parseLong(reader.readLine());
        long[] ones = new long[17];
        for (int i = 1; i < 17; i++) {
            ones[i] = 10 * ones[i - 1] + 1;
        }
        long answer = solve(ones, n, 16);
        System.out.println(answer);
    }

    private static long solve(long[] ones, long n, int idx) {
        long q = n / ones[idx];
        long r = n % ones[idx];
        long usedCount = q * idx;
        if (r == 0) {
            return usedCount;
        } else {
            long option1 = solve(ones, r, idx - 1);
            long option2 = idx + solve(ones, ones[idx] - r, idx - 1);
            return usedCount + Math.min(option1, option2);
        }
    }
}
