#include <iostream>
#include <vector>
#include <algorithm>

int main() {
    long n;
    std::cin >> n;
    std::vector<long> ones(17, 0);
    for (int i = 1; i < 17; ++i) {
        ones[i] = 10 * ones[i - 1] + 1;
    }

    std::function<long(const std::vector<long>&, long, int)> solve = [&](const std::vector<long>& ones, long n, int idx) -> long {
        long q = n / ones[idx];
        long r = n % ones[idx];
        long usedCount = q * idx;
        if (r == 0) {
            return usedCount;
        } else {
            long option1 = solve(ones, r, idx - 1);
            long option2 = idx + solve(ones, ones[idx] - r, idx - 1);
            return usedCount + std::min(option1, option2);
        }
    };

    long answer = solve(ones, n, 16);
    std::cout << answer << std::endl;
    return 0;
}
